import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
terms=['formalin test termination phase 2 endogenous inhibitory opioid naloxone','formalin second phase termination nociceptive behavior opioid receptor','formalin test endogenous inhibition phase 2 behavior']
for t in terms:
 r=requests.get(u,params={'db':'pubmed','term':t,'retmode':'json','retmax':10},timeout=20)
 ids=r.json()['esearchresult']['idlist']
 print('\nQUERY:',t,'\nPMIDS:',ids)
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids: print(i,x[i].get('title'),x[i].get('pubdate'))
